.qe-h{display:flex;justify-content:space-between;align-items:center;padding:14px 16px;border-bottom:1px solid #E5E7EB;font-size:15px}.qe-x{background:none;color:#6B7280;font-size:22px;line-height:1;padding:0 6px;border:0}.qe-b{padding:14px 16px}
.qe-b label{display:block;font-size:12px;font-weight:600;color:#374151;margin:10px 0 4px}.qe-b input,.qe-b select,.qe-b textarea{width:100%;box-sizing:border-box}.qe-b .qe-r{display:flex;gap:8px;align-items:center}.qe-b .qe-r>*{flex:1}
.qe-b table{width:100%;font-size:13px;border-collapse:collapse}.qe-b td,.qe-b th{padding:5px 4px;text-align:left;vertical-align:middle}.qe-b .qe-t td:last-child{text-align:right}.qe-gt td{font-weight:700;background:#FFF1E8}
.qe-e{color:#B91C1C;font-size:13px;margin-top:10px;display:none}.qe-ok{color:#166534;font-size:13px;margin-top:10px;display:none}.qe-f{display:flex;gap:8px;justify-content:flex-end;margin-top:14px}.qe-n{font-size:12px;color:#6B7280;margin-top:8px}
