.qe-sk{display:inline-block;margin-left:6px;padding:1px 8px;border-radius:999px;background:#DCFCE7;border:1px solid #B5E3C2;color:#0B1220;font-size:11.5px;font-weight:700;white-space:nowrap}.qe-sk.lo{background:#FEE2E2;border-color:#FECACA}
.qe-rm{opacity:.45;text-decoration:line-through}.qe-sr{border:1px solid #E5E7EB;border-radius:8px;margin-top:4px;max-height:160px;overflow:auto}.qe-sr div{padding:7px 10px;cursor:pointer;font-size:13px}.qe-sr div:hover{background:#FFF1E8}
</style>
