K.qty=function(){if(!D.canMoney)return show('Quantity',blocked());
 var h='<table>'+D.items.map(function(i){return '<tr><td>'+esc(i.name)+'<br><small style="color:#6B7280">Current qty: '+i.qty+'</small>'+'<span data-sk="'+i.id+'">'+stk(i.stock)+'</span></td><td style="text-align:right"><span class="qe-st"><button type="button" data-m="-1" data-i="'+i.id+'">−</button><input type="number" min="1" data-q="'+i.id+'" value="'+i.qty+'"><button type="button" data-m="1" data-i="'+i.id+'">+</button></span></td></tr>'}).join('')+'</table>'+conf();
 var f=jform('Edit Quantity',h,'Save',function(f){var o={};D.items.forEach(function(i){o[i.id]=parseInt(q('[data-q="'+i.id+'"]',f).value,10)||0});if(!ck(f))return err(f,'Tick "Customer confirmed this change" first.');return {kind:'qty',qty:o,customer_confirmed:1}},base+'/qe/money');
 f.addEventListener('click',function(e){var m=e.target.getAttribute&&e.target.getAttribute('data-m');if(!m)return;var inp=q('[data-q="'+e.target.getAttribute('data-i')+'"]',f);inp.value=Math.max(1,(parseInt(inp.value,10)||1)+parseInt(m,10));skq(f,e.target.getAttribute('data-i'))});f.addEventListener('input',function(e){var k=e.target.getAttribute&&e.target.getAttribute('data-q');if(k!==null&&k!==undefined)skq(f,k)})};
