 function draw(f){q('#qeP',f).innerHTML=rows.map(function(r,n){return '<tr class="'+(r.rm?'qe-rm':'')+'"><td>'+esc(r.name)+stk(r.stock,r.qty)+'</td><td style="width:62px"><input type="number" min="1" data-n="'+n+'" data-k="qty" value="'+r.qty+'"></td><td style="width:82px"><input type="number" min="0" step="0.01" data-n="'+n+'" data-k="price" value="'+r.price+'"></td><td style="width:34px"><button type="button" class="g" data-rm="'+n+'" title="Remove" style="padding:4px 8px">'+(r.rm?'↩':'✕')+'</button></td></tr>'}).join('')}
 var h='<table><thead><tr><th>Product</th><th>Qty</th><th>Unit price</th><th></th></tr></thead><tbody id="qeP"></tbody></table><label>Add product (name / SKU)</label><input id="qeS" placeholder="Type to search" autocomplete="off"><div id="qeR" class="qe-sr" style="display:none"></div><label>Reason</label><select name="reason">'+opts(D.reasons,'Quantity changed')+'</select><label>Note (also used as the reason for a price change)</label><input name="note" maxlength="300">'+conf();
 var f=jform('Edit Products',h,'Save',function(f){var items=[];rows.forEach(function(r){if(!r.rm)items.push(r.id?{item_id:r.id,product_id:r.pid,name:r.name,qty:r.qty,price:r.price}:{product_id:r.pid,variant_id:r.vid||null,name:r.name,qty:r.qty,price:r.price})});if(!items.length)return err(f,'An order needs at least one product.');if(!ck(f))return err(f,'Tick "Customer confirmed this change" first.');return {kind:'products',items:items,reason:val(f,'reason'),note:val(f,'note'),customer_confirmed:1}},base+'/qe/money',true);
 draw(f);
 f.addEventListener('input',function(e){var n=e.target.getAttribute('data-n');if(n!==null){rows[n][e.target.getAttribute('data-k')]=parseFloat(e.target.value)||0;if(e.target.getAttribute('data-k')==='qty'){var td=e.target.closest('tr').firstChild,b=td.querySelector('.qe-sk');if(b&&rows[n].stock!==null&&rows[n].stock!==undefined){var nb=document.createElement('span');nb.innerHTML=stk(rows[n].stock,rows[n].qty);b.replaceWith(nb.firstElementChild)}}}});
 f.addEventListener('click',function(e){var n=e.target.getAttribute&&e.target.getAttribute('data-rm');if(n!==null&&n!==undefined&&n!==false){rows[n].rm=!rows[n].rm;draw(f)}var a=e.target.getAttribute&&e.target.getAttribute('data-add');if(a!==null&&a!==undefined&&f._res){var p=f._res[a];rows.push({id:0,pid:p.pid,vid:p.vid,name:p.name,qty:1,price:p.price,stock:p.stock,rm:false});q('#qeR',f).style.display='none';q('#qeS',f).value='';draw(f)}});
 var tm;q('#qeS',f).addEventListener('input',function(e){clearTimeout(tm);var s=e.target.value.trim(),R=q('#qeR',f);if(s.length<2){R.style.display='none';return}tm=setTimeout(function(){fetch('/admin/orders/rev-products?q='+encodeURIComponent(s),{credentials:'same-origin',headers:{Accept:'application/json'}}).then(function(r){return r.json()}).then(function(L){var res=[];L.forEach(function(p){res.push({pid:p.id,vid:null,name:p.name,price:p.price,stock:p.stock,image:p.image,sku:p.sku});(p.variants||[]).forEach(function(v){res.push({pid:p.id,vid:v.id,name:p.name+' ('+v.label+')',price:v.price,stock:v.stock,image:p.image,sku:v.sku||p.sku})})});f._res=res;R.innerHTML=res.length?res.map(function(p,n){return '<div data-add="'+n+'" style="display:flex;align-items:center;gap:8px"><img src="'+esc(p.image||'/product-placeholder')+'" alt="" loading="lazy" style="width:34px;height:34px;object-fit:contain;border:1px solid #E5E7EB;border-radius:6px;background:#fff;flex:none" onerror="this.onerror=null;this.src=\'/product-placeholder\'"><span>'+esc(p.name)+(p.sku?' · '+esc(p.sku):'')+' — '+mny(p.price)+stk(p.stock)+'</span></div>'}).join(''):'<div>No product found</div>';R.style.display='block'}).catch(function(){})},250)})};
function sumTable(){return '<table class="qe-t"><tr><td>Subtotal</td><td>'+mny(D.sub)+'</td></tr><tr><td>Discount</td><td>-'+mny(D.disc)+'</td></tr><tr><td>Delivery charge</td><td>'+mny(D.ship)+'</td></tr><tr class="qe-gt"><td>Grand Total</td><td>'+mny(D.total)+'</td></tr><tr><td>Paid</td><td>'+mny(D.paid)+'</td></tr><tr><td>Due</td><td>'+mny(D.due)+'</td></tr></table>'}
K.amount=function(){if(!D.canMoney)return show('Amount',blocked());
